def filter_primes(numbers: list) -> list:
    """
    Filter prime numbers from a list of integers.

    Parameters:
        numbers (list): A list of integers.

    Returns:
        list: A new list containing only the prime numbers in the same order.
    """
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    primes = []
    for num in numbers:
        if is_prime(num):
            primes.append(num)

    return primes
