        # Avoid duplicate checks when sides are the same
        a, b, c = sides[i], sides[i+1], sides[i+2]

        if a + b > c:
            if a + c > b:
                if b + c > a:
                    return True
                elif a + b > c and a + c > b and b + c > a:
                    return True
        else:
            return False
