def is_valid_triangle(a: int, b: int, c: int) -> bool:
    """
    Check if three integers form a valid triangle.

    Returns:
        bool: True if valid, False otherwise.
    """
    sides = [a, b, c]
    for i in range(len(sides)):
        for j in range(i + 1, len(sides)):
            for k in range(j + 1, len(sides)):
                if sides[i] + sides[j] > sides[k]:
                    return True
                if sides[j] + sides[k] > sides[i]:
                    return True
                if sides[i] + sides[k] > sides[j]:
                    return True

    return False
